bg_leia_linha.exemplo:
TEXTO_FIXO(linha, 128);
SE bg_leia_linha(stdin, linha, TAMANHO_DE(linha)) ENTAO
    ESCREVAL(linha);
FIM_SE

bg_leia_texto.exemplo:
TEXTO_FIXO(nome, 80);
SE LEIA_TEXTO(nome, TAMANHO_DE(nome)) ENTAO
    ESCREVAL(nome);
FIM_SE

bg_soma_segura.exemplo:
#define BG_USAR_EXTENSOES
#include <basicgol.h>
INTEIRO resultado = 0;
LOGICO exato = SOMA_SEGURA(MAXIMO_INTEIRO, 1, &resultado); /* FALSO */

BG_SE.exemplo:
SE idade >= 18 ENTAO
    ESCREVAL("maior de idade");
SENAO
    ESCREVAL("menor de idade");
FIM_SE

BG_ENQUANTO.exemplo:
INTEIRO i = 0;
ENQUANTO i < 3 FACA
    ESCREVAL(i);
    i = i + 1;
FIM_ENQUANTO

BG_REPITA.exemplo:
INTEIRO i = 0;
REPITA
    ESCREVAL(i);
    i = i + 1;
ATE_QUE(i >= 3);

