/* X — só no M1 */
PARA i DE 1 ATE 3 FACA
    ESCREVAL(i);
FIM_PARA

/* N — macros puras, caminho M0 */
PARA (i, 1, 3) {
    ESCREVAL(i);
}

02-referencia.code:
#include <basicgol.h>

INICIO
    INTEIRO idade = 0;
    LEIA(idade);
    SE idade >= 18 ENTAO
        ESCREVAL("maior de idade");
    SENAO
        ESCREVAL("menor de idade");
    FIM_SE
FIM

TEXTO_FIXO(nome, 80);
SE LEIA_TEXTO(nome, TAMANHO_DE(nome)) ENTAO
    ESCREVAL(nome);
SENAO
    ESCREVAL("nao foi possivel ler");
FIM_SE

TEXTO_FIXO(nome, 32);
SE JUNTA_TEXTO(nome, TAMANHO_DE(nome), "BASIC", "GOL") ENTAO
    ESCREVAL(nome);
FIM_SE

