    INTEIRO idade = 0;
    TEXTO_FIXO(nome, 64);

    ESCREVA("Nome: ");
    LEIA_TEXTO(nome, TAMANHO_DE(nome));
    ESCREVA("Idade: ");
    LEIA(idade);

    ESCREVAL(nome);
    ESCREVAL(idade);
FIM

